from pathlib import Path
import xml.etree.ElementTree as ET
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak

ROOT=Path(__file__).resolve().parents[1];JUNIT=ROOT/'test-results'/'junit.xml';OUT=ROOT/'output'/'pdf'/'SBB-Oxygen-House-Admin-Inventory-Test-Report.pdf'
if not JUNIT.exists():raise SystemExit('Run npm run test:inventory:all first.')
rows=[]
for suite in ET.parse(JUNIT).getroot().findall('testsuite'):
 for case in suite.findall('testcase'):
  name=case.get('name','')
  if 'INV-MATRIX-' not in name:continue
  fail=case.find('failure');status='FAILED' if fail is not None else ('SKIPPED' if case.find('skipped') is not None else 'PASSED')
  finding='Search accepted the value but all 16 rows remained visible.' if status=='FAILED' else 'Verified.'
  rows.append([name.split('›')[-1].strip(),suite.get('hostname','Unknown'),status,f"{float(case.get('time',0)):.1f}s",finding])
if len(rows)!=24:raise SystemExit(f'Expected 24 Inventory matrix results, found {len(rows)}. Run npm run test:inventory:all.')
p=sum(r[2]=='PASSED' for r in rows);f=sum(r[2]=='FAILED' for r in rows);sk=sum(r[2]=='SKIPPED' for r in rows)
OUT.parent.mkdir(parents=True,exist_ok=True);styles=getSampleStyleSheet();navy=colors.HexColor('#102331');teal=colors.HexColor('#0B6980');line=colors.HexColor('#B9C9D1');green=colors.HexColor('#DDF4E6');red=colors.HexColor('#FADADA');amber=colors.HexColor('#FFF0C2')
title=ParagraphStyle('Title',parent=styles['Title'],fontSize=19,leading=23,textColor=navy,spaceAfter=3*mm);h=ParagraphStyle('H',parent=styles['Heading1'],fontSize=13,leading=16,textColor=teal,spaceBefore=3*mm,spaceAfter=2*mm);body=ParagraphStyle('Body',parent=styles['BodyText'],fontSize=8.5,leading=12,textColor=navy);small=ParagraphStyle('Small',parent=body,fontSize=7,leading=9);tiny=ParagraphStyle('Tiny',parent=body,fontSize=5.7,leading=6.6)
def footer(canvas,doc):
 canvas.saveState();canvas.setStrokeColor(line);canvas.line(14*mm,12*mm,196*mm,12*mm);canvas.setFillColor(colors.HexColor('#607783'));canvas.setFont('Helvetica',6.5);canvas.drawString(14*mm,8*mm,'SBB Oxygen House - Admin Inventory Test Report');canvas.drawRightString(196*mm,8*mm,f'Page {doc.page}');canvas.restoreState()
def table(data,widths,header=teal,repeat=1,style=small):
 t=Table([[Paragraph(str(c),style) for c in row] for row in data],colWidths=widths,repeatRows=repeat)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),header),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.35,line),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),4)]));return t
doc=SimpleDocTemplate(str(OUT),pagesize=A4,leftMargin=14*mm,rightMargin=14*mm,topMargin=14*mm,bottomMargin=17*mm,title='Admin Inventory Test Report',author='Calibur Automation')
story=[Paragraph('SBB OXYGEN HOUSE',ParagraphStyle('Brand',parent=small,textColor=teal,fontSize=10,leading=12)),Paragraph('ADMIN INVENTORY TEST REPORT',title),Paragraph('UI, functional, validation, generated test data, nonfunctional and web/mobile compatibility evidence',body),Spacer(1,5*mm)]
summary=Table([['Target','Matrix','Passed','Failed','Skipped'],['/admin/inventory',len(rows),p,f,sk]],colWidths=[72*mm,27*mm,27*mm,27*mm,27*mm]);summary.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ALIGN',(1,0),(-1,-1),'CENTER'),('GRID',(0,0),(-1,-1),.4,line),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8),('PADDING',(0,0),(-1,-1),6)]));story +=[summary,Spacer(1,5*mm),Paragraph('Executive result',h),Paragraph(f'The latest compatibility matrix completed with <b>{p} passed, {f} failed and {sk} skipped</b>. All eight functional profile checks failed for the same reproducible search defect. All eight UI checks and all eight combined accessibility, HTTPS and runtime-quality checks passed.',body),Paragraph('Confirmed defect',h)]
story.append(table([['Severity','Feature','Observed result','Expected result'],['High','Product/SKU search','Entering an exact existing product name leaves all 16 inventory rows visible in every tested web and mobile profile.','Only matching rows should remain visible; an impossible query should show zero rows.']],[25*mm,35*mm,70*mm,50*mm],navy))
story +=[Paragraph('Safe generated-data lifecycle',h),Paragraph('The mutation test selected an exact live product row, captured its original on-hand quantity, added <b>1</b>, verified the new quantity, removed <b>1</b>, and verified the original value was restored. A guarded cleanup sets the exact original quantity if an intermediate step fails. No inventory record was deleted; delete behavior was tested by opening the warning and choosing Cancel.',body),Paragraph('Focused Chrome evidence',h),Paragraph('The focused suite produced 11 passes and 1 search failure after correcting the tab locator. It verified the table identity, stock arithmetic, Add/Remove/Set panels, invalid numeric data, history, delete cancellation, UI, accessibility, performance, security, responsive layout and runtime quality. The separate lifecycle passed.',body),Paragraph('Test data',h)]
story.append(table([['Data set','Values','Purpose'],['Invalid stock','0, -1, 1.5','Native numeric constraints reject zero, negative and fractional stock adjustments.'],['Generated adjustment','1','Safe Add then Remove round-trip.'],['No-match query','INV-NO-MATCH-9F7A2C','Verify empty search result; currently exposes the defect.'],['Live rows','First 10 records','Verify Available = On hand - Reserved.']],[42*mm,48*mm,90*mm]))
story +=[PageBreak(),Paragraph('Detailed coverage',title)]
coverage=[('Functional identity','Authenticated route, heading, description, table headers and live rows.'),('Stock arithmetic','Available quantity equals on-hand minus reserved for sampled live records.'),('Search','Exact product and impossible-query filtering; failed in every profile.'),('Adjustment dialogs','Add, Remove and Set tabs, labels, numeric input and action buttons.'),('Validation','Zero, negative and fractional adjustment values.'),('Generated data lifecycle','Add 1, verify; Remove 1, verify exact restoration.'),('History','Selected-product history dialog opens and identifies the product.'),('Delete safety','Permanent-delete warning opens; Cancel preserves all records.'),('UI/responsive','Controls usable and no document-width overflow at configured viewports.'),('Accessibility','Axe WCAG 2 A/AA scan; zero critical violations.'),('Performance','Authenticated Inventory page ready in under 10 seconds.'),('Security','HTTPS and authenticated exact route without login redirect.'),('Runtime quality','No uncaught JavaScript errors or HTTP 5xx responses.'),('Compatibility','Chrome, Edge, Firefox and Safari-compatible engines on web and mobile.')]
story +=[table([['Testing area','What was verified']]+coverage,[43*mm,137*mm]),Spacer(1,4*mm),Paragraph('Browser interpretation',h),Paragraph('Chrome and Edge profiles use installed vendor browsers. Firefox uses Playwright Firefox. Safari-compatible profiles use Playwright WebKit on Windows and provide engine-level compatibility evidence, not certification on physical Apple Safari devices.',body),Paragraph('Release recommendation',h),Paragraph('Stock arithmetic, adjustment modes, generated-data round-trip, history, delete cancellation, UI, critical accessibility, performance, HTTPS and runtime quality are operational. Release acceptance should remain conditional on fixing Inventory search and rerunning the 24-case matrix.',body)]
story +=[PageBreak(),Paragraph('Compatibility matrix results',title),Paragraph('Each row below comes from the latest JUnit execution generated by npm run test:inventory:all.',body),Spacer(1,3*mm)]
data=[['Test case','Profile','Result','Time','Finding']]+rows;dt=table(data,[70*mm,35*mm,19*mm,14*mm,42*mm],teal,1,tiny);cmd=[]
for i,r in enumerate(rows,1):cmd.append(('BACKGROUND',(2,i),(2,i),green if r[2]=='PASSED' else red if r[2]=='FAILED' else amber))
dt.setStyle(TableStyle(cmd));story.append(dt);doc.build(story,onFirstPage=footer,onLaterPages=footer);print(OUT)
